contracts/CandidateDatabase.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.8;

import {ICandidateDatabase} from "./interfaces/ICandidateDatabase.sol";
import {AdminManagement} from "./shared/AdminManagement.sol";
import {ElectionUtils} from "./lib/ElectionUtils.sol";

/**
 * @title CandidateDatabase Contract
 * @author Masum Reza
 * @notice This contract manages candidate registration and profiles for an electronic voting system
 * @dev This contract implements:
 *      - Self-registration management for candidates
 *      - Admin functions for candidate management
 *      - Importing functionality from other candidate databases
 */

/// @notice Thrown when a candidate under the age of 18 attempts to register
error CandidateDatabase__NotEligible();

/// @notice Thrown when a non-registered candidate tries to perform a restricted action
error CandidateDatabase__NotRegistered();

/// @notice Thrown when a candidate tries to register again
error CandidateDatabase__AlreadyRegistered();

/// @notice Thrown when import operations fail
error CandidateDatabase__ImportFailed();

/// @notice Thrown when an invalid address is provided
error CandidateDatabase__InvalidAddress();

contract CandidateDatabase is ICandidateDatabase, AdminManagement {
    uint256 private constant MIN_ELIGIBLE_AGE = 18;

    /**
     * @notice Stores details for a single candidate
     * @dev The registrationTimestamp serves as both a timestamp and a registration flag
     *    - If > 0, candidate is registered
     */
    struct Candidate {
        string name;
        string presentAddress;
        string email;
        string qualifications;
        string manifesto;
        Gender gender;
        uint256 dateOfBirthEpoch;
        uint256 registrationTimestamp;
    }

    /// @dev Main storage for candidate information
    mapping(address => Candidate) private s_candidates;

    /// @dev Array of all registered candidate addresses for enumeration
    address[] private s_candidateAddresses;

    /**
     * @notice Ensures the candidate meets minimum age requirements
     * @param _dateOfBirthEpoch Date of birth as Unix timestamp
     */
    modifier onlyEligible(uint256 _dateOfBirthEpoch) {
        if (ElectionUtils.calculateAge(_dateOfBirthEpoch) < MIN_ELIGIBLE_AGE)
            revert CandidateDatabase__NotEligible();
        _;
    }

    /**
     * @notice Ensures the address belongs to a registered candidate
     * @param _candidateAddress Address to check for registration
     */
    modifier onlyRegistered(address _candidateAddress) {
        if (s_candidates[_candidateAddress].registrationTimestamp == 0)
            revert CandidateDatabase__NotRegistered();
        _;
    }

    /**
     * @notice Ensures the address does not belong to an already registered candidate
     * @param _candidateAddress Address to check for registration
     */
    modifier onlyNotRegistered(address _candidateAddress) {
        if (s_candidates[_candidateAddress].registrationTimestamp > 0)
            revert CandidateDatabase__AlreadyRegistered();
        _;
    }

    /**
     * @notice Ensures the provided address is not the zero address
     * @param _candidateAddress Address to validate
     */
    modifier onlyValidAddress(address _candidateAddress) {
        if (_candidateAddress == address(0))
            revert CandidateDatabase__InvalidAddress();
        _;
    }

    /**
     * @notice Internal function to add a new candidate to the database
     * @dev Used by both self-registration and admin functions
     * @param _candidateAddress Address of the candidate to add
     * @param _name Name of the candidate
     * @param _dateOfBirthEpoch Date of birth as Unix timestamp
     * @param _gender Gender of the candidate
     * @param _presentAddress Present address of the candidate
     * @param _email Email address of the candidate
     * @param _qualifications Educational qualifications of the candidate
     * @param _manifesto Election manifesto of the candidate
     */
    function _addCandidate(
        address _candidateAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    )
        internal
        onlyEligible(_dateOfBirthEpoch)
        onlyNotRegistered(_candidateAddress)
    {
        s_candidates[_candidateAddress] = Candidate({
            name: _name,
            dateOfBirthEpoch: _dateOfBirthEpoch,
            gender: _gender,
            presentAddress: _presentAddress,
            email: _email,
            qualifications: _qualifications,
            manifesto: _manifesto,
            registrationTimestamp: block.timestamp
        });

        s_candidateAddresses.push(_candidateAddress);
    }

    /**
     * @notice Internal function to update candidate details
     * @dev Used by both self-update and admin functions
     * @param _candidateAddress Address of the candidate to update
     * @param _name Updated name
     * @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
     * @param _gender Updated gender
     * @param _presentAddress Updated present address
     * @param _email Updated email address
     * @param _qualifications Updated qualifications
     * @param _manifesto Updated manifesto
     */
    function _updateCandidate(
        address _candidateAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    )
        internal
        onlyEligible(_dateOfBirthEpoch)
        onlyRegistered(_candidateAddress)
    {
        Candidate storage candidate = s_candidates[_candidateAddress];

        // Update details but preserve registrationTimestamp
        candidate.name = _name;
        candidate.dateOfBirthEpoch = _dateOfBirthEpoch;
        candidate.gender = _gender;
        candidate.presentAddress = _presentAddress;
        candidate.email = _email;
        candidate.qualifications = _qualifications;
        candidate.manifesto = _manifesto;
    }

    /**
     * @notice Internal function to remove a candidate from the database
     * @dev Removes from mapping and updates the address array for enumeration
     * @param _candidateAddress Address of the candidate to remove
     */
    function _deleteCandidate(
        address _candidateAddress
    ) internal onlyRegistered(_candidateAddress) {
        // remove candidate from mapping
        delete s_candidates[_candidateAddress];

        // swap candidate with last element and pop
        uint256 length = s_candidateAddresses.length;
        for (uint256 i = 0; i < length; ) {
            if (s_candidateAddresses[i] == _candidateAddress) {
                s_candidateAddresses[i] = s_candidateAddresses[length - 1];
                s_candidateAddresses.pop();
                break;
            }
            unchecked {
                ++i;
            }
        }
    }

    /**
     * @notice Register a new candidate in the system
     * @dev Self-registration function for candidates
     * @param _name Name of the candidate
     * @param _dateOfBirthEpoch Date of birth as Unix timestamp
     * @param _gender Gender of the candidate (0 for Male, 1 for Female)
     * @param _presentAddress Present address of the candidate
     * @param _email Email address of the candidate
     * @param _qualifications Educational qualifications of the candidate
     * @param _manifesto Election manifesto of the candidate
     */
    function addCandidate(
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external override {
        _addCandidate(
            msg.sender,
            _name,
            _dateOfBirthEpoch,
            _gender,
            _presentAddress,
            _email,
            _qualifications,
            _manifesto
        );
        emit CandidateRegistered(msg.sender);
    }

    /**
     * @notice Update candidate information
     * @dev Self-update function for registered candidates
     * @param _name Updated name
     * @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
     * @param _gender Updated gender
     * @param _presentAddress Updated address
     * @param _email Updated email
     * @param _qualifications Updated qualifications
     * @param _manifesto Updated manifesto
     */
    function updateCandidate(
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external override {
        _updateCandidate(
            msg.sender,
            _name,
            _dateOfBirthEpoch,
            _gender,
            _presentAddress,
            _email,
            _qualifications,
            _manifesto
        );
        emit CandidateUpdated(msg.sender);
    }

    /**
     * @notice Allows a registered candidate to delete their own registration
     * @dev Self-removal function for registered candidates
     */
    function deleteCandidate() external override {
        _deleteCandidate(msg.sender);
        emit CandidateDeleted(msg.sender);
    }

    /**
     * @notice Admin function to add a candidate directly
     * @dev Only owner/admins can call this function
     * @param _candidateAddress Address of the candidate to add
     * @param _name Name of the candidate
     * @param _dateOfBirthEpoch Date of birth as Unix timestamp
     * @param _gender Gender of the candidate
     * @param _presentAddress Present address of the candidate
     * @param _email Email address of the candidate
     * @param _qualifications Educational qualifications of the candidate
     * @param _manifesto Election manifesto of the candidate
     */
    function adminAddCandidate(
        address _candidateAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external override onlyAdmin onlyValidAddress(_candidateAddress) {
        _addCandidate(
            _candidateAddress,
            _name,
            _dateOfBirthEpoch,
            _gender,
            _presentAddress,
            _email,
            _qualifications,
            _manifesto
        );
        emit AdminAddedCandidate(_candidateAddress, msg.sender);
    }

    /**
     * @notice Admin function to update candidate details
     * @dev Only owner/admins can call this function
     * @param _candidateAddress Address of the candidate to update
     * @param _name Updated name
     * @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
     * @param _gender Updated gender
     * @param _presentAddress Updated present address
     * @param _email Updated email address
     * @param _qualifications Updated qualifications
     * @param _manifesto Updated manifesto
     */
    function adminUpdateCandidate(
        address _candidateAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external override onlyAdmin onlyValidAddress(_candidateAddress) {
        _updateCandidate(
            _candidateAddress,
            _name,
            _dateOfBirthEpoch,
            _gender,
            _presentAddress,
            _email,
            _qualifications,
            _manifesto
        );
        emit AdminUpdatedCandidate(_candidateAddress, msg.sender);
    }

    /**
     * @notice Admin function to remove a candidate
     * @dev Only owner/admins can call this function
     * @param _candidateAddress Address of the candidate to remove
     */
    function adminRemoveCandidate(
        address _candidateAddress
    ) external override onlyAdmin onlyValidAddress(_candidateAddress) {
        _deleteCandidate(_candidateAddress);
        emit AdminRemovedCandidate(_candidateAddress, msg.sender);
    }

    /**
     * @notice Import a specific candidate from another CandidateDatabase contract
     * @dev Only owner/admins can call this function
     * @param _sourceContract The address of the source CandidateDatabase contract
     * @param _candidateAddress The address of the candidate to import
     */
    function adminImportCandidate(
        address _sourceContract,
        address _candidateAddress
    ) external override onlyAdmin onlyNotRegistered(_candidateAddress) {
        ICandidateDatabase source = ICandidateDatabase(_sourceContract);

        try source.getCandidateDetails(_candidateAddress) returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            ICandidateDatabase.Gender gender,
            string memory presentAddress,
            string memory email,
            string memory qualifications,
            string memory manifesto,
            uint256 /* registrationTimestamp */
        ) {
            _addCandidate(
                _candidateAddress,
                name,
                dateOfBirthEpoch,
                gender,
                presentAddress,
                email,
                qualifications,
                manifesto
            );

            emit AdminAddedCandidate(_candidateAddress, msg.sender);
            emit CandidatesImported(_sourceContract, 1);
        } catch {
            revert CandidateDatabase__ImportFailed();
        }
    }

    /**
     * @notice Batch import selected candidates from another CandidateDatabase contract
     * @dev Only owner/admins can call this function
     * @param _sourceContract The address of the source CandidateDatabase contract
     * @param _candidateAddresses Array of candidate addresses to import
     */
    function adminBatchImportCandidates(
        address _sourceContract,
        address[] calldata _candidateAddresses
    ) external override onlyAdmin {
        ICandidateDatabase source = ICandidateDatabase(_sourceContract);
        uint256 importedCount = 0;

        uint256 length = _candidateAddresses.length;
        for (uint256 i = 0; i < length; ) {
            address candidateAddress = _candidateAddresses[i];

            // Skip if candidate is already registered
            if (s_candidates[candidateAddress].registrationTimestamp > 0) {
                unchecked {
                    ++i;
                }
                continue;
            }

            try source.getCandidateDetails(candidateAddress) returns (
                string memory name,
                uint256 dateOfBirthEpoch,
                ICandidateDatabase.Gender gender,
                string memory presentAddress,
                string memory email,
                string memory qualifications,
                string memory manifesto,
                uint256 /* registrationTimestamp */
            ) {
                _addCandidate(
                    candidateAddress,
                    name,
                    dateOfBirthEpoch,
                    gender,
                    presentAddress,
                    email,
                    qualifications,
                    manifesto
                );

                emit AdminAddedCandidate(candidateAddress, msg.sender);

                unchecked {
                    ++i;
                    ++importedCount;
                }
            } catch {
                // Continue to next candidate if this one fails
                unchecked {
                    ++i;
                }
                continue;
            }
        }

        emit CandidatesImported(_sourceContract, importedCount);
    }

    /**
     * @notice Import all candidates from another CandidateDatabase contract
     * @dev Only owner/admins can call this function
     * @param _sourceContract The address of the source CandidateDatabase contract
     */
    function adminImportAllCandidates(
        address _sourceContract
    ) external override onlyAdmin {
        ICandidateDatabase source = ICandidateDatabase(_sourceContract);
        address[] memory candidates;

        // Use try/catch to handle potential errors from external calls
        try source.getAllCandidates() returns (address[] memory _candidates) {
            candidates = _candidates;
        } catch {
            revert CandidateDatabase__ImportFailed();
        }

        uint256 importedCount = 0;

        uint256 length = candidates.length;
        for (uint256 i = 0; i < length; ) {
            address candidateAddress = candidates[i];

            // Skip if candidate is already registered in this contract
            if (s_candidates[candidateAddress].registrationTimestamp > 0) {
                unchecked {
                    ++i;
                }
                continue;
            }

            try source.getCandidateDetails(candidateAddress) returns (
                string memory name,
                uint256 dateOfBirthEpoch,
                ICandidateDatabase.Gender gender,
                string memory presentAddress,
                string memory email,
                string memory qualifications,
                string memory manifesto,
                uint256 /* registrationTimestamp */
            ) {
                _addCandidate(
                    candidateAddress,
                    name,
                    dateOfBirthEpoch,
                    gender,
                    presentAddress,
                    email,
                    qualifications,
                    manifesto
                );

                emit AdminAddedCandidate(candidateAddress, msg.sender);
                unchecked {
                    ++i;
                    ++importedCount;
                }
            } catch {
                // Continue to next candidate if this one fails
                unchecked {
                    ++i;
                }
                continue;
            }
        }

        emit CandidatesImported(_sourceContract, importedCount);
    }

    /**
     * @notice Get details of a specific candidate (publicly accessible)
     * @param _candidateAddress Address of the candidate
     * @return name The candidate's name
     * @return dateOfBirthEpoch The candidate's date of birth as Unix timestamp
     * @return gender The candidate's gender
     * @return presentAddress The candidate's address
     * @return email The candidate's email
     * @return qualifications The candidate's qualifications
     * @return manifesto The candidate's manifesto
     * @return registrationTimestamp When the candidate registered
     */
    function getCandidateDetails(
        address _candidateAddress
    )
        external
        view
        override
        onlyRegistered(_candidateAddress)
        returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            Gender gender,
            string memory presentAddress,
            string memory email,
            string memory qualifications,
            string memory manifesto,
            uint256 registrationTimestamp
        )
    {
        Candidate memory candidate = s_candidates[_candidateAddress];
        return (
            candidate.name,
            candidate.dateOfBirthEpoch,
            candidate.gender,
            candidate.presentAddress,
            candidate.email,
            candidate.qualifications,
            candidate.manifesto,
            candidate.registrationTimestamp
        );
    }

    /**
     * @notice Get your own candidate details
     * @return name Your name
     * @return dateOfBirthEpoch Your date of birth as Unix timestamp
     * @return gender Your gender
     * @return presentAddress Your present address
     * @return email Your email
     * @return qualifications Your qualifications
     * @return manifesto Your manifesto
     * @return registrationTimestamp When you registered
     */
    function getMyDetails()
        external
        view
        override
        onlyRegistered(msg.sender)
        returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            Gender gender,
            string memory presentAddress,
            string memory email,
            string memory qualifications,
            string memory manifesto,
            uint256 registrationTimestamp
        )
    {
        Candidate memory candidate = s_candidates[msg.sender];
        return (
            candidate.name,
            candidate.dateOfBirthEpoch,
            candidate.gender,
            candidate.presentAddress,
            candidate.email,
            candidate.qualifications,
            candidate.manifesto,
            candidate.registrationTimestamp
        );
    }

    /**
     * @notice Get the list of all registered candidate addresses (publicly accessible)
     * @return List of all candidate addresses
     */
    function getAllCandidates()
        external
        view
        override
        returns (address[] memory)
    {
        return s_candidateAddresses;
    }

    /**
     * @notice Get the total number of registered candidates
     * @return count The count of registered candidates
     */
    function getCandidateCount()
        external
        view
        override
        returns (uint256 count)
    {
        return s_candidateAddresses.length;
    }

    /**
     * @notice Get your own registration status
     * @return isRegistered Whether you are registered as a candidate
     */
    function getMyRegistrationStatus()
        external
        view
        override
        returns (bool isRegistered)
    {
        return s_candidates[msg.sender].registrationTimestamp > 0;
    }

    /**
     * @notice Get a candidate's registration status
     * @param _candidateAddress Address of the candidate
     * @return isRegistered Whether the candidate is registered
     */
    function getCandidateRegistrationStatus(
        address _candidateAddress
    ) external view override returns (bool isRegistered) {
        return s_candidates[_candidateAddress].registrationTimestamp > 0;
    }

    /**
     * @notice Get your current age based on stored date of birth
     * @return age Your current age in years
     */
    function getMyAge()
        external
        view
        onlyRegistered(msg.sender)
        returns (uint256 age)
    {
        return
            ElectionUtils.calculateAge(
                s_candidates[msg.sender].dateOfBirthEpoch
            );
    }
}

contracts/ElectionDatabase.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.8;

/**
 * @title ElectionDatabase Contract
 * @author Masum Reza
 * @notice Handles creation, management, and voting of elections using external voter and candidate databases
 * @dev Functions specifically prepended with admin may only be called by the contract owner or admins
 * @dev Other functions are accessible to all users, except otherwise specified by modifiers
 */

import {IVoterDatabase} from "./interfaces/IVoterDatabase.sol";
import {ICandidateDatabase} from "./interfaces/ICandidateDatabase.sol";
import {AdminManagement} from "./shared/AdminManagement.sol";

/// @notice Thrown when a voter is not registered in the voter database
error ElectionDatabase__VoterNotRegistered();

/// @notice Thrown when a voter has already voted in the election
error ElectionDatabase__VoterAlreadyVoted();

/// @notice Thrown when a candidate is not registered in the candidate database
error ElectionDatabase__CandidateNotRegistered();

/// @notice Thrown when a candidate is already registered in the election
error ElectionDatabase__CandidateAlreadyEnrolled();

/// @notice Thrown when a restricted action is attempted during an active election
error ElectionDatabase__ElectionActive();

/// @notice Thrown when an election is not currently accepting votes
error ElectionDatabase__ElectionClosed();

/// @notice Thrown when the requested election does not exist
error ElectionDatabase__ElectionNotFound();

/// @notice Thrown when an election has no contestants/candidates enrolled
error ElectionDatabase__ElectionHasNoContestant();

/// @notice Thrown when an invalid address (0x0) is provided
error ElectionDatabase__InvalidAddress();

/**
 * @title ElectionDatabase Contract
 * @author Masum Reza
 * @notice This contract manages election creation, candidate enrollment, and voting processes
 * @dev This contract implements:
 *      - Admin functions for election management
 *      - Candidate self-enrollment for elections
 *      - Secure voting functionality
 *      - Integration with VoterDatabase and CandidateDatabase
 */
contract ElectionDatabase is AdminManagement {
    /**
     * @notice Stores details for a single election
     * @dev The registrationTimestamp serves as both a timestamp and a registration flag
     *    - If > 0, election is registered
     */
    struct Election {
        string name;
        string description;
        // address of candidates who are also registered in CandidateDatabase
        address[] candidates;
        // candidate -> votes to that candidate
        mapping(address => uint256) votesPerCandidate;
        // voter -> who they voted for
        mapping(address => address) voterToChosenCandidate;
        // voter -> timestamp when they voted in this specific election (0 if not voted)
        mapping(address => uint256) voterToVoteTimestamp;
        // used to track whether the election is active or not
        bool isActive;
        uint256 totalVotes;
        // If > 0, election is registered. Acts as creation timestamp
        uint256 registrationTimestamp;
    }

    /// @dev References to external databases
    IVoterDatabase private immutable s_voterDB;
    ICandidateDatabase private immutable s_candidateDB;

    /// @dev Election storage and tracking
    uint256 private s_electionCounter;
    mapping(uint256 => Election) private s_elections;
    uint256[] private s_electionIds;

    /// @notice Emitted when a new election is created
    event AdminCreatedElection(
        uint256 indexed electionId,
        string name,
        address indexed creator
    );

    /// @notice Emitted when an election's details are updated
    event AdminUpdatedElection(
        uint256 indexed electionId,
        string name,
        address indexed updater
    );

    /// @notice Emitted when an election is deleted
    event AdminDeletedElection(
        uint256 indexed electionId,
        string name,
        address indexed remover
    );

    /// @notice Emitted when a candidate is added to an election by an admin
    event AdminEnrolledCandidate(
        uint256 indexed electionId,
        address indexed candidate,
        address indexed adder
    );

    /// @notice Emitted when a candidate is removed from an election by an admin
    event AdminRemovedCandidate(
        uint256 indexed electionId,
        address indexed candidate,
        address indexed remover
    );

    /// @notice Emitted when a candidate enrolls themselves in an election
    event CandidateEnrolled(
        uint256 indexed electionId,
        address indexed candidate
    );

    /// @notice Emitted when a candidate withdraws themselves from an election
    event CandidateWithdrawn(
        uint256 indexed electionId,
        address indexed candidate
    );

    /// @notice Emitted when a voter votes for a candidate
    event VoterVoted(
        uint256 indexed electionId,
        address indexed voter,
        address indexed candidate
    );

    /// @notice Emitted when an election is opened for voting
    event ElectionOpened(uint256 indexed electionId, address indexed admin);

    /// @notice Emitted when an election is closed
    event ElectionClosed(uint256 indexed electionId, address indexed admin);

    /**
     * @notice Ensures the election exists
     * @param _electionId ID of the election to check
     */
    modifier onlyRegisteredElection(uint256 _electionId) {
        if (s_elections[_electionId].registrationTimestamp == 0)
            revert ElectionDatabase__ElectionNotFound();
        _;
    }

    /**
     * @notice Ensures the election is open for voting
     * @param _electionId ID of the election to check
     */
    modifier onlyOpenElection(uint256 _electionId) {
        if (!s_elections[_electionId].isActive)
            revert ElectionDatabase__ElectionClosed();
        _;
    }

    /**
     * @notice Ensures the election is closed/inactive
     * @param _electionId ID of the election to check
     */
    modifier onlyClosedElection(uint256 _electionId) {
        if (s_elections[_electionId].isActive)
            revert ElectionDatabase__ElectionActive();
        _;
    }

    /**
     * @notice Ensures the caller is a registered voter
     */
    modifier onlyRegisteredVoter() {
        if (!s_voterDB.adminGetRegistrationStatus(msg.sender)) {
            revert ElectionDatabase__VoterNotRegistered();
        }
        _;
    }

    /**
     * @notice Ensures the address belongs to a registered candidate
     * @param _candidate Address to check for registration in CandidateDatabase
     */
    modifier onlyRegisteredCandidate(address _candidate) {
        if (!s_candidateDB.getCandidateRegistrationStatus(_candidate)) {
            revert ElectionDatabase__CandidateNotRegistered();
        }
        _;
    }

    /**
     * @notice Ensures the address belongs to a candidate enrolled in the specified election
     * @param _electionId ID of the election
     * @param _candidate Address to check for enrollment
     */
    modifier onlyEnrolledCandidate(uint256 _electionId, address _candidate) {
        Election storage election = s_elections[_electionId];
        bool validCandidate = false;
        for (uint256 i = 0; i < election.candidates.length; i++) {
            if (election.candidates[i] == _candidate) {
                validCandidate = true;
                break;
            }
        }
        if (!validCandidate) revert ElectionDatabase__CandidateNotRegistered();
        _;
    }

    /**
     * @notice Contract constructor
     * @param _voterDBAddress Address of the VoterDatabase contract
     * @param _candidateDBAddress Address of the CandidateDatabase contract
     */
    constructor(address _voterDBAddress, address _candidateDBAddress) {
        if (_voterDBAddress == address(0) || _candidateDBAddress == address(0))
            revert ElectionDatabase__InvalidAddress();

        s_voterDB = IVoterDatabase(_voterDBAddress);
        s_candidateDB = ICandidateDatabase(_candidateDBAddress);
        s_electionCounter = 0;
    }

    /**
     * @notice Creates a new election with given name and description
     * @dev Only owner/admins can call this function
     * @param _name Name of the election
     * @param _description Description of the election
     */
    function adminCreateElection(
        string memory _name,
        string memory _description
    ) external onlyAdmin {
        uint256 electionId = s_electionCounter;

        Election storage newElection = s_elections[electionId];
        newElection.name = _name;
        newElection.description = _description;
        newElection.isActive = false;
        newElection.totalVotes = 0;
        newElection.registrationTimestamp = block.timestamp; // Set timestamp to register the election

        s_electionIds.push(electionId);
        s_electionCounter++;

        emit AdminCreatedElection(electionId, _name, msg.sender);
    }

    /**
     * @notice Updates an existing election's details
     * @dev Only owner/admins can call this function
     * @param _electionId ID of the election to update
     * @param _name New name for the election
     * @param _description New description for the election
     */
    function adminUpdateElection(
        uint256 _electionId,
        string memory _name,
        string memory _description
    ) external onlyAdmin onlyRegisteredElection(_electionId) {
        Election storage election = s_elections[_electionId];

        election.name = _name;
        election.description = _description;

        emit AdminUpdatedElection(_electionId, _name, msg.sender);
    }

    /**
     * @notice Deletes an existing election
     * @dev Only owner/admins can call this function
     * @param _electionId ID of the election to delete
     */
    function adminDeleteElection(
        uint256 _electionId
    ) external onlyAdmin onlyRegisteredElection(_electionId) {
        // Store the name before marking as not registered
        string memory electionName = s_elections[_electionId].name;

        // Delete from the mapping
        delete s_elections[_electionId];

        // Remove from electionIds array using swap and pop
        for (uint256 i = 0; i < s_electionIds.length; i++) {
            if (s_electionIds[i] == _electionId) {
                s_electionIds[i] = s_electionIds[s_electionIds.length - 1];
                s_electionIds.pop();
                break;
            }
        }

        emit AdminDeletedElection(_electionId, electionName, msg.sender);
    }

    /**
     * @notice Opens an election for voting
     * @dev Only owner/admins can call this function
     * @dev Election must have at least one candidate to be opened
     * @param _electionId ID of the election to open
     */
    function adminOpenElection(
        uint256 _electionId
    ) external onlyAdmin onlyRegisteredElection(_electionId) {
        Election storage election = s_elections[_electionId];

        // Prevent opening elections with no candidates
        if (election.candidates.length == 0) {
            revert ElectionDatabase__ElectionHasNoContestant();
        }

        election.isActive = true;
        emit ElectionOpened(_electionId, msg.sender);
    }

    /**
     * @notice Closes an election from voting
     * @dev Only owner/admins can call this function
     * @param _electionId ID of the election to close
     */
    function adminCloseElection(
        uint256 _electionId
    ) external onlyAdmin onlyRegisteredElection(_electionId) {
        Election storage election = s_elections[_electionId];
        election.isActive = false;
        emit ElectionClosed(_electionId, msg.sender);
    }

    /**
     * @notice Allows a candidate to enroll themselves in an election
     * @dev Candidate must be registered in CandidateDatabase
     * @dev Election must be in closed state
     * @param _electionId ID of the election to enroll in
     */
    function enrollCandidate(
        uint256 _electionId
    )
        external
        onlyRegisteredElection(_electionId)
        onlyClosedElection(_electionId)
        onlyRegisteredCandidate(msg.sender)
    {
        Election storage election = s_elections[_electionId];

        // Check if candidate is already registered in this election
        for (uint256 i = 0; i < election.candidates.length; i++) {
            if (election.candidates[i] == msg.sender) {
                revert ElectionDatabase__CandidateAlreadyEnrolled();
            }
        }

        election.candidates.push(msg.sender);

        emit CandidateEnrolled(_electionId, msg.sender);
    }

    /**
     * @notice Allows a candidate to withdraw themselves from an election
     * @dev Election must be in closed state
     * @param _electionId ID of the election to withdraw from
     */
    function withdrawCandidate(
        uint256 _electionId
    )
        external
        onlyRegisteredElection(_electionId)
        onlyClosedElection(_electionId)
    {
        Election storage election = s_elections[_electionId];

        // Find and remove the candidate
        bool found = false;
        for (uint256 i = 0; i < election.candidates.length; i++) {
            if (election.candidates[i] == msg.sender) {
                // Swap with last element and pop
                election.candidates[i] = election.candidates[
                    election.candidates.length - 1
                ];
                election.candidates.pop();
                found = true;
                break;
            }
        }

        if (!found) {
            revert ElectionDatabase__CandidateNotRegistered();
        }

        emit CandidateWithdrawn(_electionId, msg.sender);
    }

    /**
     * @notice Allows a registered voter to vote for a candidate in an active election
     * @param _electionId ID of the election
     * @param _candidate Address of the candidate to vote for
     */
    function vote(
        uint256 _electionId,
        address _candidate
    )
        external
        onlyRegisteredElection(_electionId)
        onlyOpenElection(_electionId)
        onlyEnrolledCandidate(_electionId, _candidate)
        onlyRegisteredVoter
    {
        Election storage election = s_elections[_electionId];

        // Check if voter already voted in this specific election
        if (election.voterToVoteTimestamp[msg.sender] > 0)
            revert ElectionDatabase__VoterAlreadyVoted();

        // Record the vote
        election.votesPerCandidate[_candidate]++;
        election.voterToChosenCandidate[msg.sender] = _candidate;
        election.voterToVoteTimestamp[msg.sender] = block.timestamp;
        election.totalVotes++;

        // Mark the voter as having voted in the voter database
        s_voterDB.adminMarkVoted(msg.sender);

        emit VoterVoted(_electionId, msg.sender, _candidate);
    }

    /**
     * @notice Adds a candidate to a registered election by an admin
     * @dev Only owner/admins can call this function
     * @param _electionId ID of the election
     * @param _candidate Address of the candidate to add
     */
    function adminEnrollCandidate(
        uint256 _electionId,
        address _candidate
    )
        external
        onlyAdmin
        onlyRegisteredElection(_electionId)
        onlyRegisteredCandidate(_candidate)
    {
        Election storage election = s_elections[_electionId];

        // Check if candidate is already registered in this election
        for (uint256 i = 0; i < election.candidates.length; i++) {
            if (election.candidates[i] == _candidate) {
                revert ElectionDatabase__CandidateAlreadyEnrolled();
            }
        }

        election.candidates.push(_candidate);

        emit AdminEnrolledCandidate(_electionId, _candidate, msg.sender);
    }

    /**
     * @notice Removes a candidate from an election by an admin
     * @dev Only owner/admins can call this function
     * @param _electionId ID of the election
     * @param _candidate Address of the candidate to remove
     */
    function adminWithdrawCandidate(
        uint256 _electionId,
        address _candidate
    ) external onlyAdmin onlyRegisteredElection(_electionId) {
        Election storage election = s_elections[_electionId];

        // Find and remove the candidate
        bool found = false;
        for (uint256 i = 0; i < election.candidates.length; i++) {
            if (election.candidates[i] == _candidate) {
                // Swap with last element and pop
                election.candidates[i] = election.candidates[
                    election.candidates.length - 1
                ];
                election.candidates.pop();
                found = true;
                break;
            }
        }

        if (!found) {
            revert ElectionDatabase__CandidateNotRegistered();
        }

        emit AdminRemovedCandidate(_electionId, _candidate, msg.sender);
    }

    /**
     * @notice Returns the vote count of a candidate in a specific election
     * @param _electionId ID of the election
     * @param _candidate Address of the candidate
     * @return Number of votes received by the candidate
     */
    function getVotesOfCandidate(
        uint256 _electionId,
        address _candidate
    ) external view onlyRegisteredElection(_electionId) returns (uint256) {
        return s_elections[_electionId].votesPerCandidate[_candidate];
    }

    /**
     * @notice Returns whether the election is currently active
     * @param _electionId ID of the election
     * @return Status of the election (true if active)
     */
    function getElectionStatus(
        uint256 _electionId
    ) external view onlyRegisteredElection(_electionId) returns (bool) {
        return s_elections[_electionId].isActive;
    }

    /**
     * @notice Returns comprehensive details of an election
     * @param _electionId ID of the election
     * @return name Name of the election
     * @return description Description of the election
     * @return isActive Whether the election is currently active
     * @return candidates Array of candidate addresses enrolled in the election
     * @return totalVotes Total number of votes cast in the election
     * @return registrationTimestamp When the election was created
     */
    function getElectionDetails(
        uint256 _electionId
    )
        external
        view
        onlyRegisteredElection(_electionId)
        returns (
            string memory name,
            string memory description,
            bool isActive,
            address[] memory candidates,
            uint256 totalVotes,
            uint256 registrationTimestamp
        )
    {
        Election storage election = s_elections[_electionId];
        return (
            election.name,
            election.description,
            election.isActive,
            election.candidates,
            election.totalVotes,
            election.registrationTimestamp
        );
    }

    /**
     * @notice Returns the total number of elections created
     * @return Count of all elections
     */
    function getElectionCount() external view returns (uint256) {
        return s_electionIds.length;
    }

    /**
     * @notice Returns all election IDs
     * @return Array of all election IDs
     */
    function getAllElectionIds() external view returns (uint256[] memory) {
        return s_electionIds;
    }

    /**
     * @notice Returns the list of registered candidates for a given election
     * @param _electionId ID of the election
     * @return Array of candidate addresses enrolled in the election
     */
    function getRegisteredCandidates(
        uint256 _electionId
    )
        external
        view
        onlyRegisteredElection(_electionId)
        returns (address[] memory)
    {
        return s_elections[_electionId].candidates;
    }

    /**
     * @notice Returns the total number of votes cast in an election
     * @param _electionId ID of the election
     * @return Total vote count
     */
    function getTotalVoteCount(
        uint256 _electionId
    ) external view onlyRegisteredElection(_electionId) returns (uint256) {
        return s_elections[_electionId].totalVotes;
    }

    /**
     * @notice Returns the winning candidate (highest votes) for a given election
     * @param _electionId ID of the election
     * @return Address of the winning candidate
     */
    function getWinner(
        uint256 _electionId
    ) external view onlyRegisteredElection(_electionId) returns (address) {
        Election storage election = s_elections[_electionId];
        uint256 maxVotes = 0;
        address winnerAddress = address(0);

        for (uint256 i = 0; i < election.candidates.length; i++) {
            address candidate = election.candidates[i];
            uint256 votes = election.votesPerCandidate[candidate];
            if (votes > maxVotes) {
                maxVotes = votes;
                winnerAddress = candidate;
            }
        }

        return winnerAddress;
    }

    /**
     * @notice Check if a voter has already voted in a specific election
     * @param _electionId ID of the election
     * @param _voter Address of the voter to check
     * @return True if the voter has voted in this election
     */
    function hasVoted(
        uint256 _electionId,
        address _voter
    ) external view onlyRegisteredElection(_electionId) returns (bool) {
        return s_elections[_electionId].voterToVoteTimestamp[_voter] > 0;
    }

    /**
     * @notice Get the timestamp when a voter voted in a specific election
     * @param _electionId ID of the election
     * @param _voter Address of the voter
     * @return Timestamp when the voter voted (0 if not voted)
     */
    function getVoteTimestamp(
        uint256 _electionId,
        address _voter
    ) external view onlyRegisteredElection(_electionId) returns (uint256) {
        return s_elections[_electionId].voterToVoteTimestamp[_voter];
    }

    /**
     * @notice Check who a voter voted for in a specific election
     * @dev Only viewable by registered voters (themselves)
     * @param _electionId ID of the election
     * @return Address of the candidate voted for (address(0) if not voted)
     */
    function getVoterChoice(
        uint256 _electionId
    )
        external
        view
        onlyRegisteredElection(_electionId)
        onlyRegisteredVoter
        returns (address)
    {
        if (s_elections[_electionId].voterToVoteTimestamp[msg.sender] == 0) {
            return address(0); // Voter hasn't voted
        }
        return s_elections[_electionId].voterToChosenCandidate[msg.sender];
    }

    /**
     * @notice Returns the voting and candidate databases being used
     * @return voterDB Address of the VoterDatabase contract
     * @return candidateDB Address of the CandidateDatabase contract
     */
    function getDatabases()
        external
        view
        returns (address voterDB, address candidateDB)
    {
        return (address(s_voterDB), address(s_candidateDB));
    }
}

