// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.8;

/**
 * @title ICandidateDatabase Interface
 * @author Based on CandidateDatabase by Masum Reza
 * @notice Interface for the CandidateDatabase contract
 * @dev Defines the external functions for interaction with the CandidateDatabase contract
 */

interface ICandidateDatabase {
    /// @notice Enum representing gender
    enum Gender {
        Male,
        Female
    }

    /// @notice Emitted when a new candidate is registered
    /// @param candidate The address of the newly registered candidate
    event CandidateRegistered(address indexed candidate);

    /// @notice Emitted when a candidate updates their profile
    /// @param candidate The address of the updated candidate
    event CandidateUpdated(address indexed candidate);

    /// @notice Emitted when a candidate is deleted/unregistered
    /// @param candidate The address of the deleted candidate
    event CandidateDeleted(address indexed candidate);

    /// @notice Emitted when candidate data is imported
    /// @param sourceContract Address of the contract data was imported from
    /// @param candidatesImported Number of candidates successfully imported
    event CandidatesImported(
        address indexed sourceContract,
        uint256 candidatesImported
    );

    /// @notice Emitted when admin adds a candidate
    /// @param candidate The address of the candidate added by admin
    /// @param admin The admin who added the candidate
    event AdminAddedCandidate(address indexed candidate, address indexed admin);

    /// @notice Emitted when admin updates a candidate
    /// @param candidate The address of the candidate updated by admin
    /// @param admin The admin who updated the candidate
    event AdminUpdatedCandidate(
        address indexed candidate,
        address indexed admin
    );

    /// @notice Emitted when admin removes a candidate
    /// @param candidate The address of the candidate removed by admin
    /// @param admin The admin who removed the candidate
    event AdminRemovedCandidate(
        address indexed candidate,
        address indexed admin
    );

    /// @notice Register yourself as a candidate
    /// @param _name Candidate's full name
    /// @param _dateOfBirthEpoch Candidate's date of birth as Unix timestamp
    /// @param _gender Candidate's gender (0 for Male, 1 for Female)
    /// @param _presentAddress Candidate's present address
    /// @param _email Candidate's email address
    /// @param _qualifications Candidate's educational qualifications
    /// @param _manifesto Candidate's election manifesto or platform
    function addCandidate(
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external;

    /// @notice Update your candidate profile
    /// @param _name Updated name
    /// @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
    /// @param _gender Updated gender
    /// @param _presentAddress Updated present address
    /// @param _email Updated email address
    /// @param _qualifications Updated qualifications
    /// @param _manifesto Updated manifesto
    function updateCandidate(
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external;

    /// @notice Allows a registered candidate to delete their own registration
    function deleteCandidate() external;

    /// @notice Admin function to add a candidate directly
    /// @param _candidateAddress Address of the candidate to add
    /// @param _name Name of the candidate
    /// @param _dateOfBirthEpoch Date of birth as Unix timestamp
    /// @param _gender Gender of the candidate
    /// @param _presentAddress Present address of the candidate
    /// @param _email Email of the candidate
    /// @param _qualifications Qualifications of the candidate
    /// @param _manifesto Manifesto of the candidate
    function adminAddCandidate(
        address _candidateAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external;

    /// @notice Admin function to update candidate details
    /// @param _candidateAddress Address of the candidate to update
    /// @param _name Updated name
    /// @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
    /// @param _gender Updated gender
    /// @param _presentAddress Updated present address
    /// @param _email Updated email
    /// @param _qualifications Updated qualifications
    /// @param _manifesto Updated manifesto
    function adminUpdateCandidate(
        address _candidateAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        string memory _qualifications,
        string memory _manifesto
    ) external;

    /// @notice Admin function to remove a candidate
    /// @param _candidateAddress Address of the candidate to remove
    function adminRemoveCandidate(address _candidateAddress) external;

    /// @notice Import a specific candidate from another CandidateDatabase contract
    /// @param _sourceContract The address of the source CandidateDatabase contract
    /// @param _candidateAddress The address of the candidate to import
    function adminImportCandidate(
        address _sourceContract,
        address _candidateAddress
    ) external;

    /// @notice Batch import selected candidates from another CandidateDatabase contract
    /// @param _sourceContract The address of the source CandidateDatabase contract
    /// @param _candidateAddresses Array of candidate addresses to import
    function adminBatchImportCandidates(
        address _sourceContract,
        address[] calldata _candidateAddresses
    ) external;

    /// @notice Import all candidates from another CandidateDatabase contract
    /// @param _sourceContract The address of the source CandidateDatabase contract
    function adminImportAllCandidates(address _sourceContract) external;

    /// @notice Get full details of a specific candidate
    /// @param _candidateAddress Address of the candidate
    /// @return name The name of the candidate
    /// @return dateOfBirthEpoch The date of birth of the candidate as Unix timestamp
    /// @return gender The gender of the candidate
    /// @return presentAddress The present address of the candidate
    /// @return email The email address of the candidate
    /// @return qualifications The qualifications of the candidate
    /// @return manifesto The election manifesto of the candidate
    /// @return registrationTimestamp When the candidate registered
    function getCandidateDetails(
        address _candidateAddress
    )
        external
        view
        returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            Gender gender,
            string memory presentAddress,
            string memory email,
            string memory qualifications,
            string memory manifesto,
            uint256 registrationTimestamp
        );

    /// @notice Get the list of all registered candidate addresses
    /// @return Array of candidate wallet addresses
    function getAllCandidates() external view returns (address[] memory);

    /// @notice Get your full candidate details
    /// @return name Your name
    /// @return dateOfBirthEpoch Your date of birth as Unix timestamp
    /// @return gender Your gender
    /// @return presentAddress Your present address
    /// @return email Your email
    /// @return qualifications Your qualifications
    /// @return manifesto Your election manifesto
    /// @return registrationTimestamp When you registered
    function getMyDetails()
        external
        view
        returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            Gender gender,
            string memory presentAddress,
            string memory email,
            string memory qualifications,
            string memory manifesto,
            uint256 registrationTimestamp
        );

    /// @notice Get your own registration status
    /// @return isRegistered Whether you are registered as a candidate
    function getMyRegistrationStatus()
        external
        view
        returns (bool isRegistered);

    /// @notice Get a candidate's registration status
    /// @param _candidateAddress Address of the candidate
    /// @return isRegistered Whether the candidate is registered
    function getCandidateRegistrationStatus(
        address _candidateAddress
    ) external view returns (bool isRegistered);

    /// @notice Get number of registered candidates
    /// @return count The number of registered candidates
    function getCandidateCount() external view returns (uint256 count);
}

contracts/interfaces/IVoterDatabase.sol.content:
// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.8;

/**
 * @title IVoterDatabase Interface
 * @author Based on VoterDatabase by Masum Reza
 * @notice Interface for the VoterDatabase contract
 * @dev Defines the external functions for interaction with the VoterDatabase contract
 */

interface IVoterDatabase {
    /// @notice Enum representing gender
    enum Gender {
        Male,
        Female
    }

    /// @notice Emitted when a new voter is registered
    /// @param voter The address of the newly registered voter
    event VoterRegistered(address indexed voter);

    /// @notice Emitted when a voter updates their information
    /// @param voter The address of the voter who updated info
    event VoterUpdated(address indexed voter);

    /// @notice Emitted when a voter is deleted from the system
    /// @param voter The address of the voter whose info was deleted
    event VoterDeleted(address indexed voter);

    /// @notice Emitted when a voter is marked as having voted
    /// @param voter The address of the voter who voted
    event VoterVoted(address indexed voter);

    /// @notice Emitted when voter data is imported
    /// @param sourceContract Address of the contract data was imported from
    /// @param votersImported Number of voters successfully imported
    event VotersImported(
        address indexed sourceContract,
        uint256 votersImported
    );

    /// @notice Emitted when admin adds a voter
    /// @param voter The address of the voter added by admin
    /// @param admin The admin who added the voter
    event AdminAddedVoter(address indexed voter, address indexed admin);

    /// @notice Emitted when admin updates a voter
    /// @param voter The address of the voter updated by admin
    /// @param admin The admin who updated the voter
    event AdminUpdatedVoter(address indexed voter, address indexed admin);

    /// @notice Emitted when admin removes a voter
    /// @param voter The address of the voter removed by admin
    /// @param admin The admin who removed the voter
    event AdminRemovedVoter(address indexed voter, address indexed admin);

    /// @notice Emitted when admin resets a voter's voting status
    /// @param voter The address of the voter whose status was reset
    /// @param admin The admin who reset the voter's status
    event AdminUpdatedVotingStatus(
        address indexed voter,
        address indexed admin
    );

    /// @notice Register a new voter
    /// @param _name Name of the voter
    /// @param _dateOfBirthEpoch Date of birth as Unix timestamp
    /// @param _gender Gender of the voter (0 for Male, 1 for Female)
    /// @param _presentAddress Present address of the voter
    /// @param _email Email address of the voter
    function addVoter(
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email
    ) external;

    /// @notice Update voter information (only if registered and not yet voted)
    /// @param _name Updated name
    /// @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
    /// @param _gender Updated gender
    /// @param _presentAddress Updated address
    /// @param _email Updated email
    function updateVoter(
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email
    ) external;

    /// @notice Allows a registered voter to delete their own registration
    function deleteVoter() external;

    /// @notice Mark a voter as having voted
    function markVoted() external;

    /// @notice Admin function to add a voter directly
    /// @param _voterAddress Address of the voter to add
    /// @param _name Name of the voter
    /// @param _dateOfBirthEpoch Date of birth as Unix timestamp
    /// @param _gender Gender of the voter
    /// @param _presentAddress Present address of the voter
    /// @param _email Email address of the voter
    /// @param _timesVoted Initial voting status of the voter
    function adminAddVoter(
        address _voterAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        uint256 _timesVoted
    ) external;

    /// @notice Admin function to update voter details
    /// @param _voterAddress Address of the voter to update
    /// @param _name Updated name
    /// @param _dateOfBirthEpoch Updated date of birth as Unix timestamp
    /// @param _gender Updated gender
    /// @param _presentAddress Updated present address
    /// @param _email Updated email address
    /// @param _timesVoted Updated voting count
    function adminUpdateVoter(
        address _voterAddress,
        string memory _name,
        uint256 _dateOfBirthEpoch,
        Gender _gender,
        string memory _presentAddress,
        string memory _email,
        uint256 _timesVoted
    ) external;

    /// @notice Admin function to remove a voter
    /// @param _voterAddress Address of the voter to remove
    function adminRemoveVoter(address _voterAddress) external;

    /// @notice Admin function to mark a voter as having voted
    /// @param _voterAddress Address of the voter
    function adminMarkVoted(address _voterAddress) external;

    /// @notice Import a specific voter from another VoterDatabase contract
    /// @param _sourceContract The address of the source VoterDatabase contract
    /// @param _voterAddress The address of the voter to import
    function adminImportVoter(
        address _sourceContract,
        address _voterAddress
    ) external;

    /// @notice Batch import selected voters from another VoterDatabase contract
    /// @param _sourceContract The address of the source VoterDatabase contract
    /// @param _voterAddresses Array of voter addresses to import
    function adminBatchImportVoters(
        address _sourceContract,
        address[] calldata _voterAddresses
    ) external;

    /// @notice Import all voters from another VoterDatabase contract
    /// @param _sourceContract The address of the source VoterDatabase contract
    function adminImportAllVoters(address _sourceContract) external;

    /// @notice Get details of a specific voter
    /// @param _voterAddress Address of the voter
    /// @return name The voter's name
    /// @return dateOfBirthEpoch The voter's date of birth as Unix timestamp
    /// @return gender The voter's gender
    /// @return presentAddress The voter's address
    /// @return email The voter's email
    /// @return timesVoted Number of times the voter has voted
    /// @return registrationTimestamp When the voter registered as Unix timestamp
    function adminGetVoterDetails(
        address _voterAddress
    )
        external
        view
        returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            Gender gender,
            string memory presentAddress,
            string memory email,
            uint256 timesVoted,
            uint256 registrationTimestamp
        );

    /// @notice Get the total number of registered voters
    /// @return The count of registered voters
    function adminGetVoterCount() external view returns (uint256);

    /// @notice Get addresses of all registered voters
    /// @return Array of addresses of all registered voters
    function adminGetAllVoters() external view returns (address[] memory);

    /// @notice Get your own voter details
    /// @return name Your name
    /// @return dateOfBirthEpoch Your date of birth as Unix timestamp
    /// @return gender Your gender
    /// @return presentAddress Your present address
    /// @return email Your email address
    /// @return timesVoted How many times you have voted
    /// @return registrationTimestamp When you registered
    function getMyDetails()
        external
        view
        returns (
            string memory name,
            uint256 dateOfBirthEpoch,
            Gender gender,
            string memory presentAddress,
            string memory email,
            uint256 timesVoted,
            uint256 registrationTimestamp
        );

    /// @notice Get your own registration status
    /// @return isRegistered Whether you are registered to vote
    function getMyRegistrationStatus()
        external
        view
        returns (bool isRegistered);

    function adminGetRegistrationStatus(
        address _voterAddress
    ) external view returns (bool isRegistered);

    /// @notice Get your own voting status
    /// @return hasVoted Whether you have voted at least once
    function getMyVotingStatus() external view returns (bool hasVoted);

    /// @notice Get your current age based on stored date of birth
    /// @return Your current age in years
    function getMyAge() external view returns (uint256);
}

